(()=>{if(location.hostname==='127.0.0.1')return;let busy=false;async function mount(){const target=document.getElementById('settings');if(!target||target.classList.contains('hidden')||document.getElementById('pbStoreDesktopInstall')||busy)return;busy=true;try{const r=await fetch('/api/rental/desktop-release');if(!r.ok)return;const release=await r.json();if(!release.available)return;const box=document.createElement('div');box.id='pbStoreDesktopInstall';box.className='panel';box.style.cssText='display:block;margin:16px 0;padding:18px;border:1px solid #e4e7ec;border-radius:12px';const title=document.createElement('h3');title.textContent='برنامهٔ فروشگاه برای ویندوز';const info=document.createElement('p');info.textContent='ثبت آفیش و امور مالی به‌صورت آفلاین، همگام‌سازی و دریافت خودکار تغییرات سایت هنگام باز کردن برنامه.';const a=document.createElement('a');a.className='btn';a.textContent='دانلود برنامه ویندوز ۶۴ بیتی';a.href=release.url;a.setAttribute('download','');box.append(title,info,a);target.append(box)}catch{}finally{busy=false}}document.addEventListener('click',e=>{if(e.target.closest('[data-rental-desktop-tab="settings"],[data-rental-tab="settings"],[data-rental-bottom-tab="settings"]'))setTimeout(mount,150)});setTimeout(mount,2000)})();
